// =====================================================================
//  Constants & seeded visual randomness
// =====================================================================
var DURATION = 100;
var TPS = 20, TICK = 1 / TPS, REPLAY_TICKS = 2020, SEED = 42;
var SHOT_LIFE = 0.15;
var ETYPES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
var TTYPES = ["bolt", "cannon", "frost", "lance", "flak"];
var EIDX = {}, TIDX = {}, ii;
for (ii = 0; ii < ETYPES.length; ii++) EIDX[ETYPES[ii]] = ii;
for (ii = 0; ii < TTYPES.length; ii++) TIDX[TTYPES[ii]] = ii;
var GROUND_TILES = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
var AIR_TILES = [[0, 6], [21, 6], [21, 11], [23, 11]];
var SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
var BASE_X = 23.5, BASE_Z = 11.5;
var SPLASH_R = [0, 0.9, 0, 0, 0.7];
var HEAL_R = 1.5;

function mulberry(a) {
  return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
var vrand = mulberry(SEED);            // visual-only randomness (never Math.random)
var RT = new Float32Array(8192);
for (ii = 0; ii < RT.length; ii++) RT[ii] = vrand();
function rt(i) { return RT[i & 8191]; }
function clamp01(v) { return v < 0 ? 0 : v > 1 ? 1 : v; }
function smooth(v) { v = clamp01(v); return v * v * (3 - 2 * v); }
function lerp(a, b, f) { return a + (b - a) * f; }
function noise1(t, ch) {                // smooth seeded value noise
  var i = Math.floor(t), f = t - i, u = f * f * (3 - 2 * f);
  return lerp(rt(i * 7 + ch * 1013), rt((i + 1) * 7 + ch * 1013), u) * 2 - 1;
}

// =====================================================================
//  Replay: one run of the real simulation, observed through passive hooks
// =====================================================================
var REP = (function () {
  var tracks = [], byId = {}, frames = [], shots = [], kills = [], leaks = [], heals = [], waves = [];
  var goldAt = [], hpAt = [], waveAt = [], fallTick = -1, firstWave = null;
  var hook = {
    spawn: function (tick, e, parentId) {
      var tr = { id: e.id, type: EIDX[e.type], air: e.air, maxHp: e.maxHp, first: tick, x: [], y: [], hp: [], slow: [],
        end: 0, endTick: -1, ex: 0, ey: 0, parent: parentId, born: tick, idx: tracks.length };
      byId[e.id] = tr; tracks.push(tr);
    },
    frame: function (tick, wave, gold, baseHp, enemies) {
      var list = new Int32Array(enemies.length), i, e, tr;
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i]; tr = byId[e.id];
        if (tr.x.length === 0) tr.first = tick;
        tr.x.push(e.x / 100); tr.y.push(e.y / 100); tr.hp.push(e.hp); tr.slow.push(e.slow > 0 ? 1 : 0);
        list[i] = tr.idx;
      }
      frames[tick] = list; goldAt[tick] = gold; hpAt[tick] = baseHp; waveAt[tick] = wave;
    },
    shot: function (tick, slot, tur, tgt, hits) {
      shots.push({ tick: tick, slot: slot, type: TIDX[tur.type], tier: tur.tier, x: tgt.x / 100, y: tgt.y / 100, air: tgt.air, n: hits.length });
    },
    kill: function (tick, e, slot) {
      var tr = byId[e.id]; tr.end = 1; tr.endTick = tick; tr.ex = e.x / 100; tr.ey = e.y / 100;
      kills.push({ tick: tick, x: e.x / 100, y: e.y / 100, air: e.air, type: EIDX[e.type], id: e.id });
    },
    leak: function (tick, e, baseHp) {
      var tr = byId[e.id]; tr.end = 2; tr.endTick = tick; tr.ex = BASE_X; tr.ey = BASE_Z;
      leaks.push({ tick: tick, id: e.id, type: EIDX[e.type], hp: baseHp });
    },
    heal: function (tick, e) { heals.push({ tick: tick, x: e.x / 100, y: e.y / 100 }); },
    wave: function (tick, wave, next) { waves.push({ tick: tick, wave: wave, next: next.slice() }); },
    fall: function (tick) { fallTick = tick; }
  };
  var result = rampartSimulate(createStrategy, SEED, REPLAY_TICKS, hook);
  var lastTick = frames.length - 1;

  // board timeline from the event log (builds / upgrades / sells happen only at wave starts)
  var slotStates = [], actions = [], s, i;
  for (s = 0; s < 16; s++) slotStates.push([{ t: -1, type: -1, tier: 0, kind: "", prevType: -1, prevTier: 0 }]);
  for (i = 0; i < result.log.length; i++) {
    var L = result.log[i], code = L[1];
    if (code !== "B" && code !== "U" && code !== "S") continue;
    var st = slotStates[L[2]], prev = st[st.length - 1], t = L[0] * TICK;
    if (code === "B") st.push({ t: t, type: L[3], tier: 1, kind: "B", prevType: prev.type, prevTier: prev.tier });
    else if (code === "U") st.push({ t: t, type: prev.type, tier: L[3], kind: "U", prevType: prev.type, prevTier: prev.tier });
    else st.push({ t: t, type: -1, tier: 0, kind: "S", prevType: prev.type, prevTier: prev.tier });
    actions.push({ t: t, kind: code, slot: L[2], type: code === "B" ? L[3] : prev.type, tier: code === "U" ? L[3] : prev.tier });
  }
  // per-slot shot lists (for aiming and recoil)
