// usage: jsc diag.js -- strategy.js params.json [gold]
var __GOLD = arguments[2] ? parseInt(arguments[2], 10) : 250;
var src = readFile("sim.js").replace("var gold = 250", "var gold = __GOLD");
(0, eval)(src);
load(arguments[0]);
var __P = arguments[1] && arguments[1] !== "-" ? JSON.parse(readFile(arguments[1])) : null;
var seeds = [101, 202, 303, 404, 505, 606, 707, 808];
var tot = 0;
for (var si = 0; si < seeds.length; si++) {
  var byId = {}, goldAtWave = {}, spent = {};
  var r = rampartSimulate(createStrategy, seeds[si], 12020, {
    spawn: function (t, e) { byId[e.id] = e.type.substring(0, 3) + e.wave; },
    frame: function (tick, wave, gold, hp, en, slots) { if ((tick - 20) % 40 === 0 && tick >= 20) { var sp = 0; for (var i = 0; i < 16; i++) if (slots[i].turret) sp += slots[i].turret.spent; goldAtWave[wave] = gold; spent[wave] = sp; } }
  });
  var out = [];
  for (var i = 0; i < r.log.length; i++) if (r.log[i][1] === "L") out.push("w" + (((r.log[i][0] - 20) / 40 + 1) | 0) + ":" + byId[r.log[i][2]]);
  var econ = [];
  for (var w = 5; w <= 50; w += 5) if (spent[w] !== undefined) econ.push("w" + w + ":" + spent[w] + "+" + goldAtWave[w]);
  print("seed", seeds[si], "score", r.score, "| leaks", out.join(" "));
  print("     econ(spent+gold)", econ.join(" "));
  tot += r.score;
}
print("mean", (tot / seeds.length).toFixed(3));

