// usage: jsc tune.js -- strategy.js rngSeed seconds outFile [startFile]
load("sim.js");
load(arguments[0]);
var rs = parseInt(arguments[1], 10) || 1, budget = parseFloat(arguments[2]) || 60, outFile = arguments[3] || ("best_" + rs + ".json");
var __P = null;
// get defaults by sniffing: createStrategy uses D when __P is null -> replicate D by evaluating the source
var srcS = readFile(arguments[0]);
var dm = srcS.match(/var D = (\{[\s\S]*?\n  \});/);
var DEF = (0, eval)("(" + dm[1].replace(/;$/, "") + ")");
if (arguments[4]) { var __st = JSON.parse(readFile(arguments[4])); for (var __k in __st) DEF[__k] = __st[__k]; }

function rnd() { rs = (rs + 0x6D2B79F5) | 0; var t = Math.imul(rs ^ (rs >>> 15), 1 | rs); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
