var TRAIN = [];
for (var i = 0; i < 60; i++) TRAIN.push(5000 + i * 37);
function evalP(p) {
  __P = p;
  var sum = 0;
  for (var i = 0; i < TRAIN.length; i++) sum += rampartSimulate(createStrategy, TRAIN[i], 12020).score;
  return sum / TRAIN.length;
}
// numeric specs: [min, max, sigma]
var SPEC = (typeof __SPEC !== "undefined") ? __SPEC : null;
if (!SPEC) {
  SPEC = {};
  for (var k in DEF) {
    if (k === "order") continue;
    if (k === "resMax") SPEC[k] = [0, 1500, 150];
    else if (k === "resRate") SPEC[k] = [0, 200, 15];
    else if (k === "resW0") SPEC[k] = [0, 30, 2];
    else if (k === "resEnd") SPEC[k] = [0, 60, 3];
    else if (k === "rstMin") SPEC[k] = [0, 30, 3];
    else if (k === "rstReserve") SPEC[k] = [0, 1500, 120];
    else if (k === "rstWave") SPEC[k] = [15, 60, 3];
    else if (k === "rstLance") SPEC[k] = [0, 1, 0.6];
    else if (k === "spR") SPEC[k] = [0, 2500, 250];
    else if (k === "spPen") SPEC[k] = [0, 12, 1];
    else if (/Urg$/.test(k)) SPEC[k] = [0, 20, 0.5];
    else if (/Frac$/.test(k)) SPEC[k] = [0, 1, 0.2];
