        var pick = bi[Math.floor(rnd() * bi.length)]; var nt = "bcflk".charAt(Math.floor(rnd() * 5));
        items[pick] = nt + items[pick].substring(1); desc.push("ty" + items[pick]);
      } else { // swap the slots of two builds (and their upgrades)
