// =====================================================================
//  World rendering: a pure function of simTime
// =====================================================================
var DEBRIS_N = [5, 4, 5, 9, 6, 5, 3], DEBRIS_S = [1, 0.8, 0.9, 1.5, 1.1, 1, 0.6];
var GRAV = 9.5;
function easeOut(v) { v = clamp01(v); return 1 - (1 - v) * (1 - v); }
function lerpAngle(a, b, f) {
  var d = b - a;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  return a + d * f;
}
function shotYaw(s, sh) { return Math.atan2(sh.x - (SLOT_TILES[s][0] + 0.5), sh.y - (SLOT_TILES[s][1] + 0.5)); }
function aimYaw(s, t) {
  var a = REP.slotShots[s], n = a.length, tk = t * TPS, lo = 0, hi = n;
  if (n === 0) return -HALF_PI;
  while (lo < hi) { var mid = (lo + hi) >> 1; if (a[mid].tick <= tk) lo = mid + 1; else hi = mid; }
  var idx = lo - 1, cur = idx >= 0 ? shotYaw(s, a[idx]) : -HALF_PI;
  if (idx + 1 < n) {
    var nt = a[idx + 1].tick * TICK, lead = idx >= 0 ? Math.min(0.22, (nt - a[idx].tick * TICK) * 0.7) : 0.22;
    var u = (t - (nt - lead)) / lead;
    if (u > 0) cur = lerpAngle(cur, shotYaw(s, a[idx + 1]), smooth(u));
  }
  return cur;
}
function recoil(s, t) {
  var a = REP.slotShots[s], n = a.length, tk = t * TPS, lo = 0, hi = n;
  while (lo < hi) { var mid = (lo + hi) >> 1; if (a[mid].tick <= tk) lo = mid + 1; else hi = mid; }
  if (lo === 0) return 0;
  return Math.exp(-(t - a[lo - 1].tick * TICK) * 16);
}

function drawEnemies(k, f, animT) {
  var list = REP.frames[k], n = list.length, i, t;
  for (t = 0; t < 7; t++) { enemyPool[t].begin(); enemyPoolSlow[t].begin(); }
  blobPool.begin(); haloPool.begin(); barBgPool.begin(); barFgPool.begin();
  for (i = 0; i < n; i++) {
    var tr = REP.tracks[list[i]], j = k - tr.first, len = tr.x.length, ty = tr.type;
    var x0 = tr.x[j], z0 = tr.y[j], h0 = tr.hp[j], x1, z1, h1;
    if (j + 1 < len) { x1 = tr.x[j + 1]; z1 = tr.y[j + 1]; h1 = tr.hp[j + 1]; }
    else if (tr.end !== 0 && tr.endTick === k + 1) { x1 = tr.ex; z1 = tr.ey; h1 = tr.end === 1 ? 0 : h0; }
    else { x1 = x0; z1 = z0; h1 = h0; }
    var x = x0 + (x1 - x0) * f, z = z0 + (z1 - z0) * f;
    // heading over a few ticks, so corners turn smoothly
    var ja = j - 2 < 0 ? 0 : j - 2, jb = j + 3 >= len ? len - 1 : j + 3, jc = ja + 1 >= len ? len - 1 : ja + 1, jd = jb + 1 >= len ? len - 1 : jb + 1;
    var ax = tr.x[jb] - tr.x[ja], az = tr.y[jb] - tr.y[ja], bx = tr.x[jd] - tr.x[jc], bz = tr.y[jd] - tr.y[jc];
    if (tr.end !== 0) {
      if (j + 3 >= len) { ax += tr.ex - tr.x[len - 1]; az += tr.ey - tr.y[len - 1]; }
      if (j + 4 >= len) { bx += tr.ex - tr.x[len - 1]; bz += tr.ey - tr.y[len - 1]; }
    }
    var hx = ax + (bx - ax) * f, hz = az + (bz - az) * f, hl = Math.sqrt(hx * hx + hz * hz);
    if (hl < 1e-6) { hx = 1; hz = 0; hl = 1; }
    hx /= hl; hz /= hl;
    var yaw = Math.atan2(hx, hz), id = tr.id, age = animT - tr.born * TICK;
    var grow = 0.35 + 0.65 * smooth(age / 0.22);
    var lat = (rt(id * 3 + 1) - 0.5) * (ty === 6 ? 0.56 : ty === 3 ? 0.22 : 0.36), along = (rt(id * 3 + 2) - 0.5) * (ty === 6 ? 0.3 : 0.12), y = 0;
    if (ty === 6 && tr.parent) {              // splitlings burst out of the dying splitter
      var bu = clamp01(age / 0.32);
      lat *= easeOut(bu); along *= easeOut(bu); y = Math.sin(bu * Math.PI) * 0.38;
    }
    x += hz * lat + hx * along; z += -hx * lat + hz * along;
    var sx = grow, sy = grow, sz = grow, ph = animT * 6 + id * 1.7;
    if (ty === 2) { y = 0.8 + Math.sin(animT * 2.6 + id) * 0.07; yaw += Math.sin(animT * 1.7 + id) * 0.25; }
    else if (ty === 1) { y += Math.abs(Math.sin(ph * 1.8)) * 0.05; }
    else if (ty === 4) { sy *= 1 + Math.sin(ph) * 0.07; sx *= 1 - Math.sin(ph) * 0.04; sz = sx; }
    else if (ty === 3) { yaw += Math.sin(ph * 0.6) * 0.07; y += Math.abs(Math.sin(ph * 0.6)) * 0.025; }
    else if (ty === 0) { yaw += Math.sin(ph) * 0.1; y += Math.abs(Math.sin(ph)) * 0.03; }
    else if (ty === 6) { y += Math.abs(Math.sin(ph * 1.5)) * 0.05; }
    var slowed = tr.slow[j] === 1;
    (slowed ? enemyPoolSlow[ty] : enemyPool[ty]).addYaw(x, y, z, yaw, sx, sy, sz, 1, 1, 1);
    if (ty === 2) {
      blobPool.addYaw(x + 0.12, 0.035, z - 0.08, 0, 0.24 * grow, 1, 0.2 * grow, 1, 1, 1);
      var gl = 0.5 + 0.12 * Math.sin(animT * 5 + id);
      if (slowed) glowPool.addBill(x, y, z, 1.05 * grow, 1.05 * grow, 0.25 * gl, 0.45 * gl, 1.0 * gl);
      else glowPool.addBill(x, y, z, 1.05 * grow, 1.05 * grow, 0.12 * gl, 0.8 * gl, 1.0 * gl);
    } else if (ty === 5) {
      var hp = 0.2 + 0.06 * Math.sin(animT * 4 + id);
      haloPool.addYaw(x, 0.04, z, 0, 0.5 * grow, 1, 0.5 * grow, 0.1 * hp, 1.0 * hp, 0.35 * hp);
      glowPool.addBill(x, 0.55, z, 1.25 * grow, 1.25 * grow, 0.05, 0.42, 0.14);
    }
    // health bar
    var frac = clamp01((h0 + (h1 - h0) * f) / tr.maxHp), bw = ENEMY_BW[ty], by = (ty === 2 ? y : 0) + ENEMY_H[ty] * grow + 0.12;
    barBgPool.addBill(x, by, z, bw + 0.05, 0.115, 0.012, 0.014, 0.02);
    if (frac > 0) {
      var off = -(1 - frac) * bw * 0.5, cr, cg, cb;
      if (frac > 0.5) { cr = (1 - frac) * 2 * 0.9 + 0.08; cg = 0.85; cb = 0.12; } else { cr = 0.98; cg = frac * 2 * 0.8 + 0.05; cb = 0.05; }
      barFgPool.addBill(x + camRight.x * off + camFwd.x * 0.03, by + camRight.y * off + camFwd.y * 0.03, z + camRight.z * off + camFwd.z * 0.03, bw * frac, 0.07, cr, cg, cb);
    }
  }
  for (t = 0; t < 7; t++) { enemyPool[t].end(); enemyPoolSlow[t].end(); }
  blobPool.end(); haloPool.end(); barBgPool.end(); barFgPool.end();
}

function drawTurrets(animT) {
  var s, t, p;
  for (t = 0; t < 5; t++) { turBasePool[t].begin(); turHeadPool[t].begin(); }
  pipPool.begin();
  for (s = 0; s < 16; s++) {
    var st = REP.slotStates[s], q = st.length - 1;
    while (q > 0 && st[q].t > animT) q--;
    var cur = st[q], sx = SLOT_TILES[s][0] + 0.5, sz = SLOT_TILES[s][1] + 0.5, age = animT - cur.t, sc = 1, type = cur.type, tier = cur.tier, sink = 0;
    if (type < 0) {
      if (cur.kind !== "S" || age >= 0.3) continue;
      type = cur.prevType; tier = 0; sc = 1 - age / 0.3; sink = -0.25 * age / 0.3;   // sold: collapses into the pad
    } else if (cur.kind === "B") {
      var u = clamp01(age / 0.32);
      sc = (1 - Math.pow(1 - u, 3)) * (1 + 0.28 * Math.sin(u * Math.PI));
      if (sc < 0.02) sc = 0.02;
    }
