    turBasePool[type].addYaw(sx, sink, sz, 0, sc, sc, sc, 1, 1, 1);
    turHeadPool[type].addYaw(sx - Math.sin(yaw) * kick, sink, sz - Math.cos(yaw) * kick, yaw, sc, sc * (1 + (type === 1 ? kick * 0.6 : 0)), sc, 1, 1, 1);
