// usage: jsc cmp.js -- strategy.js base.json 'JSON array of [label, overrides]' nSeeds [seedBase] [seedStep]
load("sim.js");
load(arguments[0]);
var __DBG = {}, __P;
var base = JSON.parse(readFile(arguments[1]));
var cfgs = JSON.parse(arguments[2]);
var n = parseInt(arguments[3], 10) || 60, sb = parseInt(arguments[4], 10) || 7000, ss = parseInt(arguments[5], 10) || 13;
var seeds = [];
for (var i = 0; i < n; i++) seeds.push(sb + i * ss);
for (var c = 0; c < cfgs.length; c++) {
  var p = JSON.parse(JSON.stringify(base)), o = cfgs[c][1];
  for (var k in o) p[k] = o[k];
  __P = p; __DBG = {};
  var t = 0, t0 = preciseTime(), worst = 0, mn = 99, sq = 0;
  for (i = 0; i < seeds.length; i++) {
    var t1 = preciseTime(), r = rampartSimulate(createStrategy, seeds[i], 12020), dt = preciseTime() - t1;
    if (dt > worst) worst = dt;
    t += r.score; sq += r.score * r.score; if (r.score < mn) mn = r.score;
  }
  var mean = t / n, sd = Math.sqrt(Math.max(0, sq / n - mean * mean));
  print(cfgs[c][0], "mean", mean.toFixed(3), "se", (sd / Math.sqrt(n)).toFixed(3), "min", mn, "desync", __DBG.desync || 0, "err", __DBG.err || "-", "conv", __DBG.conv || 0, "banked", __DBG.banked || 0, "time", (preciseTime() - t0).toFixed(1), "worstGame", worst.toFixed(2));
}

