import Cocoa
import WebKit

// usage: shot <index.html> <outDir> <width> <height> <t1,t2,...>
class Runner: NSObject, WKNavigationDelegate {
    let webView: WKWebView
    let window: NSWindow
    let outDir: String
    let times: [Double]
    var idx = 0
    init(url: URL, outDir: String, w: Int, h: Int, times: [Double]) {
        let cfg = WKWebViewConfiguration()
        let errHook = "window.__errs = []; window.addEventListener('error', function (e) { window.__errs.push(String(e.message) + ' @' + e.lineno); });"
        cfg.userContentController.addUserScript(WKUserScript(source: errHook, injectionTime: .atDocumentStart, forMainFrameOnly: true))
        webView = WKWebView(frame: NSRect(x: 0, y: 0, width: w, height: h), configuration: cfg)
        window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: w, height: h), styleMask: [.borderless], backing: .buffered, defer: false)
        window.contentView = webView
        self.outDir = outDir
        self.times = times
        super.init()
        webView.navigationDelegate = self
        webView.loadFileURL(url, allowingReadAccessTo: url.deletingLastPathComponent())
    }
    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        print("didFinish")
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.5) { self.next() }
    }
    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) { print("fail", error); exit(2) }
    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) { print("failProvisional", error); exit(2) }
    func webViewWebContentProcessDidTerminate(_ webView: WKWebView) { print("web content process terminated"); exit(4) }
    func next() {
        if idx >= times.count { print("done"); exit(0) }
        let t = times[idx]
        let js = "(function(){var s=document.getElementById('scrubber'); s.value='\(t)'; s.dispatchEvent(new Event('input')); var c=document.getElementById('stage'); var gl=null; try{gl=c.getContext('webgl2')||c.getContext('webgl');}catch(e){} return JSON.stringify({errs: window.__errs||[], seed42: window.BENCH_REPORT ? window.BENCH_REPORT.seed42 : null, three: typeof THREE, canvas: [c.width, c.height], inner: [innerWidth, innerHeight], glOk: !!gl, glErr: gl ? gl.getError() : -1});})()"
        webView.evaluateJavaScript(js) { res, err in
            print("t=\(t)", res ?? "nil", err.map { String(describing: $0) } ?? "")
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.7) {
                let conf = WKSnapshotConfiguration()
                self.webView.takeSnapshot(with: conf) { img, e in
                    if let img = img, let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) {
                        do { try png.write(to: URL(fileURLWithPath: "\(self.outDir)/shot_\(self.idx).png")); print("saved", self.idx, rep.pixelsWide, rep.pixelsHigh) } catch { print("write failed", error) }
                    } else { print("snapshot failed", e.map { String(describing: $0) } ?? "") }
                    self.idx += 1
                    self.next()
                }
            }
        }
    }
}
let args = CommandLine.arguments
let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let times = args[5].split(separator: ",").map { Double($0)! }
let runner = Runner(url: URL(fileURLWithPath: args[1]), outDir: args[2], w: Int(args[3])!, h: Int(args[4])!, times: times)
DispatchQueue.main.asyncAfter(deadline: .now() + 75) { print("timeout"); exit(3) }
app.run()

